const { join } = await import("path");
const { pathToFileURL } = await import("url");
const root = mkdtempSync(join(tmpdir(), "koala-coverage-"));
try { mkdirSync(join(root,"tests/fixtures"),{recursive:true}); writeFileSync(join(root,"koala.config.json"), JSON.stringify({ fixturesDir:"tests/fixtures", storyDir:"docs/story/actives", scanRoot:"src", requirementsDir:"docs/requirements", storyPrefix:"B", flows:{defaults:{},patterns:[]} }));
 writeFileSync(join(root,"tests/fixtures/f.json"), JSON.stringify({ cases:[{name:"scoped", intentRef:"B-target:CHK-001:happy:0"},{name:"legacy", storyId:"B-target", intentRef:"CHK-001:edge:0"},{name:"other", intentRef:"B-other:CHK-001:adversarial:0"}] }));
 const mod = await import(pathToFileURL($root + "/packages/main/dist/core/intent-coverage.js").href); const refs = [...mod.collectFixtureIntentRefs(root,"B-target")].sort(); return { refs }; } finally { rmSync(root,{recursive:true,force:true}); }

